// lib/storage/src/content_manager/collection_meta_ops.rs L36-47
/// Create alternative name for a collection.
/// Collection will be available under both names for search, retrieve,
#[derive(Debug, Deserialize, Serialize, JsonSchema, PartialEq, Eq, Hash, Clone)]
#[serde(rename_all = "snake_case")]
pub struct CreateAlias {
    pub collection_name: String,
    pub alias_name: String,
}

#[derive(...)]
pub struct CreateAliasOperation {
    pub create_alias: CreateAlias,
}

// L78-86: untagged enum — 缺 alias_name 字段时三个 variant 全部失配 → 400
#[derive(...)]
#[serde(untagged)]
pub enum AliasOperations {
    CreateAlias(CreateAliasOperation),
    DeleteAlias(DeleteAliasOperation),
    RenameAlias(RenameAliasOperation),
}

// src/actix/api/collections_api.rs L180-195: REST handler 直接 Json<ChangeAliasesOperation> 反序列化
#[post("/collections/aliases")]
async fn update_aliases(..., operation: Json<ChangeAliasesOperation>, ...) {
    dispatcher.submit_collection_meta_op(CollectionMetaOperations::ChangeAliases(operation.0), ...)
}

